using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class MartBillboardProbe{static MartBillboardProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("MartBillboardProbe.request"))return;File.Delete("MartBillboardProbe.request");var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.ToLower().Contains("billboard")&&Vector3.Distance(f.GetComponent<Renderer>().bounds.center,new Vector3(330,33,138))<100).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/MartBillboardProbe.txt",new[]{"Selected="+(Selection.activeGameObject?Selection.activeGameObject.name:"none")}.Concat(all.Select(f=>f.name+" center="+f.GetComponent<Renderer>().bounds+" position="+f.transform.position+" rotation="+f.transform.eulerAngles+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh))));}}
